<script setup lang="ts">
import {nextTick,onMounted,onUnmounted,ref} from 'vue';
import WorkspaceSidebar from './WorkspaceSidebar.vue';
import {validCloudDirectory,validCloudWorkspaceReturn} from './cloud-files-route';
import {formatBytes} from './format-bytes';
import {analysisID,analysisKinds,analysisRelations,validAnalysisHeader,parseAnalysisPage,validAnalysisMembers,type AnalysisHeader,type AnalysisPage,type AnalysisGroup} from './directory-analysis-types';
const params=new URLSearchParams(location.search),source=ref(params.get('run')||''),selected=ref(params.get('report')||''),reports=ref<AnalysisHeader[]>([]),value=ref<AnalysisPage|null>(null),loading=ref(false),creating=ref(false),fresh=ref(false),error=ref(''),notice=ref(''),filter=ref(''),applied=ref(''),offset=ref(0),groupOffset=ref(0),historyCursor=ref(''),nextHistory=ref(''),historyMore=ref(false),memberOffsets=ref<Record<number,number>>({});
const cloudLeft=ref(validCloudDirectory(params.get('left')||'')?params.get('left')!:'');
const cloudRight=ref(validCloudDirectory(params.get('right')||'')?params.get('right')!:'');
const returnFiles=params.getAll('return_files').length===1?validCloudWorkspaceReturn(params.get('return_files')||''):'';
const analysisMode=ref<'cloud'|'sync'|'history'>(source.value?'sync':selected.value?'history':'cloud');
const reportSection=ref<HTMLElement|null>(null);
const historyLoading=ref(false),historyFresh=ref(false),historyError=ref(''),historyObserved=ref('');
let active=true,generation=0,controller:AbortController|undefined;
const current=(request:number)=>active&&request===generation;
// The stopped-service browser check exposed raw English fetch errors; the
// recovery hint also applies when this UI is opened through a NAS/proxy.
async function request(path:string,body?:unknown){const revision=generation;const response=await fetch(path,{method:body===undefined?'GET':'POST',body:body===undefined?undefined:JSON.stringify(body),headers:body===undefined?{}:{'Content-Type':'application/json'},credentials:'same-origin',signal:controller?.signal}).catch(()=>{throw Error('无法连接管理服务，请确认程序正在运行、网络连接正常后重试')});if(!current(revision))throw new DOMException('过期请求','AbortError');if(response.status===401){location.assign('/login?next='+encodeURIComponent(location.pathname+location.search));throw Error('登录已失效')}if(!response.ok)throw Error((await response.text()).slice(0,1000)||'报告读取失败');return response.json();}
function route(id:string){const q=new URLSearchParams();if(source.value)q.set('run',source.value);if(id)q.set('report',id);if(returnFiles)q.set('return_files',returnFiles);history.replaceState(null,'','/directory-analysis'+(q.size?'?'+q:''));}
// History has its own observation state: a report read is not a history
// refresh, and a failed list must not masquerade as an empty result.
async function list(before=''){
 if(!active||loading.value||creating.value)return;
 const revision=++generation;controller?.abort();controller=new AbortController();loading.value=true;historyLoading.value=true;historyFresh.value=false;historyError.value='';
 try{
  const data=await request('/api/directory-analyses'+(before?'?before='+encodeURIComponent(before):''));
  if(!current(revision))return;
  if(!Array.isArray(data.reports)||data.reports.length>50||!data.reports.every(validAnalysisHeader)||typeof data.has_more!=='boolean'||typeof data.next_before!=='string'||data.has_more&&!analysisID(data.next_before))throw Error('分析历史响应无效');
  reports.value=data.reports;historyCursor.value=before;nextHistory.value=data.next_before;historyMore.value=data.has_more;historyObserved.value=new Date().toISOString();historyFresh.value=true;error.value='';
 }catch(e){if(current(revision)){historyError.value=e instanceof Error?e.message:String(e);error.value=historyError.value}}
 finally{if(current(revision)){loading.value=false;historyLoading.value=false}}
}
async function load(id=selected.value,kind=applied.value,at=offset.value,groupsAt=groupOffset.value){if(!active||loading.value||creating.value)return;if(!analysisID(id)){error.value='请选择有效的分析报告';return}const revision=++generation;controller?.abort();controller=new AbortController();loading.value=true;fresh.value=false;try{const query=new URLSearchParams({kind,offset:String(at),group_offset:String(groupsAt)});const data=await request('/api/directory-analyses/'+id+'?'+query);if(!current(revision))return;value.value=parseAnalysisPage(data,id,kind,at,groupsAt);selected.value=id;source.value=data.analysis.source_run;applied.value=kind;offset.value=at;groupOffset.value=groupsAt;memberOffsets.value={};fresh.value=true;error.value='';route(id)}catch(e){if(current(revision))error.value=e instanceof Error?e.message:String(e)}finally{if(current(revision))loading.value=false}}
// Real 390px review found a saved report thousands of pixels above the
// clicked history row. Only explicit opens reveal/focus a current report.
async function openReport(id:string){const revision=generation+1;await load(id,'',0,0);if(!current(revision)||!fresh.value||selected.value!==id)return;await nextTick();if(!current(revision)||!fresh.value||selected.value!==id)return;reportSection.value?.focus({preventScroll:true});reportSection.value?.scrollIntoView({block:'start'});}
async function create(){if(!active||creating.value||loading.value)return;if(!analysisID(source.value)){error.value='请输入或从同步批次打开有效的运行ID';return}const revision=++generation;controller?.abort();controller=new AbortController();creating.value=true;fresh.value=false;let created='';try{const data=await request('/api/sync/runs/'+source.value+'/analysis',{});if(!current(revision))return;if(!validAnalysisHeader(data)||data.source_run!==source.value)throw Error('新报告来源无效');created=data.id;selected.value=created;notice.value='已保存独立比较报告；来源仍是该批次的历史快照，没有扫描或修改两端目录。';error.value=''}catch(e){if(current(revision))error.value=e instanceof Error?e.message:String(e)}finally{if(current(revision)){creating.value=false;if(created){filter.value='';await load(created,'',0,0)}}}}
async function createCloud(){
 if(!active||creating.value||loading.value)return;
 const left=cloudLeft.value,right=cloudRight.value;
 if(!validCloudDirectory(left)||!validCloudDirectory(right)){error.value='请输入有效的网盘绝对目录';return}
 const revision=++generation;controller?.abort();controller=new AbortController();creating.value=true;fresh.value=false;let created='';
 try{const data=await request('/api/directory-analyses',{left_root:left,right_root:right});if(!current(revision))return;if(!validAnalysisHeader(data)||data.source_kind!=='cloud_cache'||data.left_root!==left||data.right_root!==right)throw Error('缓存报告来源无效');created=data.id;selected.value=created;source.value='';notice.value='已保存缓存比较报告；未扫描或修改网盘，当前线上状态可能已变化。';error.value=''}catch(e){if(current(revision))error.value=e instanceof Error?e.message:String(e)}finally{if(current(revision)){creating.value=false;if(created){filter.value='';await load(created,'',0,0)}}}
}
function sideLabel(side:'left'|'right'){return value.value?.analysis.source_kind==='cloud_cache'?(side==='left'?'网盘（左侧）':'网盘（右侧）'):(side==='left'?'本地（左侧）':'网盘（右侧）')}
async function members(group:AnalysisGroup,at:number){if(!active||loading.value||creating.value||!fresh.value||!value.value)return;const id=value.value.analysis.id,revision=++generation;controller?.abort();controller=new AbortController();loading.value=true;try{const data=await request('/api/directory-analyses/'+id+'/groups/'+group.ordinal+'/members?offset='+at);if(!current(revision))return;if(data.report_id!==id||data.group!==group.ordinal||data.offset!==at||typeof data.has_more!=='boolean'||!validAnalysisMembers(data.members)||data.members.some((m:any)=>m.entry.sha256!==group.sha256||m.entry.size!==group.size))throw Error('重复副本分页响应无效');group.members=data.members;group.members_have_more=data.has_more;memberOffsets.value[group.ordinal]=at;error.value=''}catch(e){if(current(revision))error.value=e instanceof Error?e.message:String(e)}finally{if(current(revision))loading.value=false}}
function cloudLink(relative:string,side:'left'|'right'='right'){const root=(side==='left'?value.value?.analysis.left_root:value.value?.analysis.right_root)||'/';const full=(root==='/'?'':root)+'/'+relative;return '/cloud/files?dir='+encodeURIComponent(full.slice(0,full.lastIndexOf('/'))||'/')}
function stop(){active=false;generation++;controller?.abort();loading.value=false;creating.value=false;fresh.value=false;historyLoading.value=false;historyFresh.value=false}
async function restore(){active=true;if(selected.value)await load(selected.value);else await list()}
onMounted(()=>{window.addEventListener('pagehide',stop);window.addEventListener('pageshow',restore);document.title='目录分析 · CloudHarbor';if(source.value&&!analysisID(source.value)||selected.value&&!analysisID(selected.value)){error.value='地址中的分析来源或报告ID无效';return}if(selected.value)void load();else void list();});
onUnmounted(()=>{stop();window.removeEventListener('pagehide',stop);window.removeEventListener('pageshow',restore)});
</script>
<template><div class="workspace event-workspace directory-analysis-workspace"><WorkspaceSidebar active="/directory-analysis" @error="error=$event"/><main class="main"><header class="page-header"><div><p class="eyebrow">内容比较 · 目录结构 · 冲突证据</p><h1>目录分析</h1><p class="muted">先比较，再决定如何整理。从同步历史快照或两个网盘目录的缓存生成固定只读报告，不执行上传、下载、移动或删除。</p></div><a v-if="returnFiles" :href="returnFiles" class="button secondary" data-testid="analysis-return-files">返回网盘文件</a><a v-else href="/sync" class="button secondary">返回目录同步</a></header><p v-if="error" class="notice danger" role="alert">{{error}}</p><p v-if="notice" class="notice" role="status">{{notice}}</p><nav class="analysis-modes" aria-label="分析方式"><button v-for="mode in (['cloud','sync','history'] as const)" :key="mode" class="button secondary" :data-testid="'analysis-mode-'+mode" :aria-pressed="analysisMode===mode" @click="analysisMode=mode">{{mode==='cloud'?'比较网盘目录':mode==='sync'?'分析同步批次':'历史报告'}}</button></nav><section v-show="analysisMode==='sync'" data-analysis-mode="sync" class="analysis-card"><h2>分析同步批次</h2><p v-if="!source" class="muted">从同步批次进入即可带入来源，无需填写运行ID。<a href="/sync" class="button secondary compact">选择同步批次</a></p><form class="toolbar" @submit.prevent="create"><details class="analysis-manual-source"><summary>高级：同步批次来源</summary><label>来源运行 ID<input v-model="source" data-testid="analysis-source-run" :disabled="loading||creating" placeholder="从同步批次的“目录比较 / 冲突分析”打开"/></label></details><button class="button primary" data-testid="analysis-create" :disabled="loading||creating||!analysisID(source)">{{creating?'正在生成报告…':'分析本轮历史快照'}}</button></form><p class="muted">每次生成独立报告ID。生成时间与来源观察时间分别展示；当前两端内容可能已变化，执行整理前仍需刷新与预检。缓存比较不会触发扫描，需先在网盘缓存页完成刷新。</p></section>
<section v-show="analysisMode==='cloud'" data-analysis-mode="cloud" class="analysis-card"><h2>比较两个网盘目录</h2><form class="toolbar" @submit.prevent="createCloud"><label>左侧网盘目录<input v-model="cloudLeft" data-testid="analysis-cloud-left" :disabled="loading||creating" placeholder="/目录A"/></label><label>右侧网盘目录<input v-model="cloudRight" data-testid="analysis-cloud-right" :disabled="loading||creating" placeholder="/目录B"/></label><button class="button primary" data-testid="analysis-cloud-create" :disabled="loading||creating||!cloudLeft||!cloudRight">比较缓存内容</button></form><p class="muted">选择互不重叠的目录。缓存覆盖和文件摘要不足时仅展示已知差异，不能作为删除凭据。</p></section>
<section v-if="value" class="analysis-card" data-testid="directory-analysis-report" ref="reportSection" tabindex="-1" role="region" aria-label="目录分析报告"><header class="section-heading"><div><h2>{{analysisRelations[value.analysis.summary.relation]}}</h2><small>报告 {{value.analysis.id}}</small></div><a v-if="fresh" class="button secondary compact" :href="'/api/directory-analyses/'+value.analysis.id+'?export=1'">导出完整报告 JSON</a></header><p v-if="!fresh" class="notice">保留下方上次已读取的报告；当前读取尚未完成或失败，分页与导出暂不可用。</p><p class="muted"><template v-if="value.analysis.source_kind==='cloud_cache'">网盘缓存历史观察 · 缓存代次 {{value.analysis.cache_generation}} · 下方逐项展示观察时间</template><template v-else>来源批次 {{value.analysis.source_run}} · 原始事件 {{value.analysis.source_event_sequence}}</template><br>来源快照读取 / 记录 UTC：{{value.analysis.source_recorded_at_utc}}<br>报告生成 UTC：{{value.analysis.created_at_utc}}</p><div class="table-wrap" role="region" aria-label="目录范围与覆盖，可横向滚动" tabindex="0"><table class="analysis-summary"><thead><tr><th>范围</th><th>目录</th><th>文件 / 文件夹</th><th>文件总大小</th><th>证据覆盖</th></tr></thead><tbody><tr v-for="side in ['left','right'] as const" :key="side"><td>{{sideLabel(side)}}</td><td>{{side==='left'?value.analysis.left_root:value.analysis.right_root}}</td><td>{{value.analysis.summary[side].files}} / {{value.analysis.summary[side].directories}}</td><td>{{formatBytes(value.analysis.summary[side].bytes)}}</td><td>{{value.analysis.summary[side].listing_complete?'完整遍历快照':'遍历不完整'}}<small>内容待核对 {{value.analysis.summary[side].unverified_files}} 项</small></td></tr></tbody></table></div><p class="muted">完整重复目录同时比较相对路径、文件类型、空目录和内容。内容集合相同但结构不同，会单独列出，不视为可直接删除的完整重复目录。</p>
<h3>逐项比较</h3><form class="toolbar" @submit.prevent="load(selected,filter,0,groupOffset)"><label>项目类型<select v-model="filter" data-testid="analysis-kind" :disabled="loading||creating"><option value="">全部</option><option v-for="(label,kind) in analysisKinds" :key="kind" :value="kind">{{label}}</option></select></label><button class="button secondary compact" :disabled="loading||creating">应用筛选</button><span>当前条件 {{analysisKinds[applied]||'全部'}} · 命中 {{value.matched}} 项</span></form><div class="table-wrap" role="region" aria-label="逐项比较，可横向滚动" tabindex="0"><table data-testid="analysis-rows"><thead><tr><th>类型 / 相对路径</th><th>{{sideLabel('left')}}</th><th>{{sideLabel('right')}}</th><th>证据</th></tr></thead><tbody><tr v-for="row in value.rows" :key="row.path"><td><strong>{{analysisKinds[row.kind]}}</strong><small>{{row.path}}</small></td><td v-for="side in ['left','right'] as const" :key="side"><template v-if="row[side]"><span>{{row[side]!.directory?'📁 文件夹':'📄 '+formatBytes(row[side]!.size)}}</span><small>ID {{row[side]!.id||'未记录'}}</small><small>{{row[side]!.path}}</small><a v-if="side==='right'||value.analysis.source_kind==='cloud_cache'" class="button secondary compact" :href="cloudLink(row[side]!.path,side)">定位网盘目录</a></template><span v-else>该快照未见</span></td><td><details><summary>摘要与观察时间</summary><p v-for="side in ['left','right'] as const" :key="side"><strong>{{sideLabel(side)}}</strong><small>SHA256 {{row[side]?.sha256||'未记录'}}</small><small>观察 UTC {{row[side]?.observed_at_utc||'无独立观察时间'}}</small><small v-if="row[side]?.implied_parent">由子项路径推导的父目录结构</small></p></details></td></tr><tr v-if="!value.rows.length"><td colspan="4">当前已显示条件没有比较项目。</td></tr></tbody></table></div><div class="toolbar"><button class="button secondary compact" :disabled="!fresh||loading||offset===0" @click="load(selected,applied,Math.max(0,offset-100),groupOffset)">上一页项目</button><button class="button secondary compact" :disabled="!fresh||loading||!value.has_more" @click="load(selected,applied,offset+100,groupOffset)">下一页项目</button></div>
<h3>相同内容副本</h3><p class="muted">两端各一份可能是同步所需副本，不计为可释放空间。下方仅估算各端内部额外副本的逻辑大小，已知同身份硬链接不重复计；实际释放空间需另行核对。分析不会选定或删除任何一份。</p><section v-for="group in value.groups" :key="group.ordinal" class="duplicate-group"><div class="section-heading"><strong>{{formatBytes(group.size)}} · {{group.member_count}} 份</strong><span>左侧额外 {{formatBytes(group.redundant_bytes_left)}} · 右侧额外 {{formatBytes(group.redundant_bytes_right)}}</span></div><details><summary>内容 SHA256</summary><code>{{group.sha256}}</code></details><div class="table-wrap" role="region" :aria-label="'重复组 '+group.ordinal+' 副本，可横向滚动'" tabindex="0"><table class="analysis-members"><thead><tr><th>来源</th><th>路径</th><th>身份</th><th>观察 UTC</th></tr></thead><tbody><tr v-for="member in group.members" :key="member.side+':'+member.entry.path"><td>{{sideLabel(member.side)}}</td><td>{{member.entry.path}}</td><td>{{member.entry.id||'未记录'}}</td><td>{{member.entry.observed_at_utc||'无独立观察时间'}}</td></tr></tbody></table></div><div class="toolbar"><button class="button secondary compact" :disabled="loading||!fresh||!(memberOffsets[group.ordinal]||0)" @click="members(group,Math.max(0,(memberOffsets[group.ordinal]||0)-20))">上一批副本</button><button class="button secondary compact" :disabled="loading||!fresh||!group.members_have_more" @click="members(group,(memberOffsets[group.ordinal]||0)+20)">下一批副本</button></div></section><p v-if="!value.groups.length" class="muted">当前没有可显示的已校验同内容副本组。</p><div class="toolbar"><button class="button secondary compact" :disabled="loading||!fresh||groupOffset===0" @click="load(selected,applied,offset,Math.max(0,groupOffset-10))">上一页重复组</button><button class="button secondary compact" :disabled="loading||!fresh||!value.groups_have_more" @click="load(selected,applied,offset,groupOffset+10)">下一页重复组</button></div></section>
<section v-show="analysisMode==='history'" data-analysis-mode="history" class="analysis-card"><header class="section-heading"><h2>已保存的分析报告</h2><button class="button secondary compact" :disabled="loading||creating" @click="list()">读取最新记录</button></header><p v-if="historyError" class="notice danger" role="alert">历史列表读取失败：{{historyError}}</p><p v-if="historyLoading" role="status">{{historyObserved?'正在重新读取历史，暂显示上次结果。':'正在读取历史列表…'}}</p><p v-if="historyObserved" class="muted"><span data-testid="analysis-history-observed">列表读取 UTC：{{historyObserved}}</span><span v-if="!historyFresh"> · 保留上次读取，当前列表尚未重新核对。</span></p><div class="table-wrap" role="region" aria-label="分析报告历史，可横向滚动" tabindex="0"><table class="analysis-history"><thead><tr><th>生成 UTC</th><th>左侧 / 右侧</th><th>分析结果</th><th>操作</th></tr></thead><tbody><tr v-for="report in reports" :key="report.id"><td>{{report.created_at_utc}}</td><td>{{report.left_root}}<small>{{report.right_root}}</small></td><td>{{analysisRelations[report.summary.relation]}}</td><td><button class="button secondary compact" :disabled="loading||creating" @click="openReport(report.id)">查看报告</button></td></tr><tr v-if="!reports.length"><td colspan="4">{{historyLoading?'正在读取历史列表…':historyError?'历史列表读取失败，请重试。':!historyObserved?'尚未读取历史列表，可点击读取最新记录。':historyCursor?'这一页没有分析报告，请回到最新记录。':'尚无保存的分析报告。'}}</td></tr></tbody></table></div><div class="toolbar"><button class="button secondary compact" :disabled="loading||creating||!historyCursor" @click="list()">回到最新</button><button class="button secondary compact" :disabled="loading||creating||!historyMore" @click="list(nextHistory)">更早报告</button></div></section><p v-if="loading" role="status">正在读取固定报告…</p></main></div></template>
<style scoped>.analysis-modes{display:flex;gap:8px;flex-wrap:wrap;margin:12px 0}.analysis-modes [aria-pressed=true]{background:#eef2ff;border-color:#a8b9ef;color:#294aa8}.analysis-manual-source summary{padding:8px 0}.analysis-manual-source label{margin-top:8px}.analysis-card{background:#fff;border:1px solid #dfe6ef;border-radius:12px;margin:18px 0;padding:20px}.section-heading,.toolbar{display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap}.toolbar{justify-content:flex-start;margin:12px 0}h2{margin:0 0 10px}.table-wrap{overflow:auto}table{width:100%;min-width:650px;border-collapse:collapse;text-align:left}th,td{padding:10px 12px;border-bottom:1px solid #e5ebf3;vertical-align:top;font-size:13px;overflow-wrap:anywhere}th{background:#f5f7fb;font-size:12px;white-space:nowrap}small{display:block;color:#67768c;font-size:12px;margin-top:5px}label{display:grid;gap:7px}input,select{font:inherit;border:1px solid #cbd5e2;border-radius:7px;padding:8px 10px;max-width:100%;box-sizing:border-box}input{min-width:280px}.duplicate-group{border:1px solid #dce4ef;border-radius:8px;padding:14px;margin:12px 0}code{display:block;overflow-wrap:anywhere}summary{cursor:pointer;color:#245cba}.muted{overflow-wrap:anywhere}@media(max-width:760px){.analysis-card{padding:14px}input{min-width:160px;width:100%}}
/* Real narrow review measured 407px history rows from an 85px path column. */
.analysis-history{min-width:940px}
.analysis-history th:nth-child(1),.analysis-history th:nth-child(3){width:22%}
.analysis-history th:nth-child(2){width:44%}
.analysis-history th:nth-child(4){width:12%}
[data-testid=directory-analysis-report]{scroll-margin-top:calc(var(--app-header-height,64px) + 18px)}
.table-wrap[role=region]:focus-visible,[data-testid=directory-analysis-report]:focus-visible{outline:3px solid #b5c9ff;outline-offset:3px}

/* The same download-table column defaults also narrowed report paths and
   left/right evidence. Each analysis table now declares its own columns. */
.analysis-summary{min-width:1000px}
.analysis-summary th:nth-child(1){width:14%}
.analysis-summary th:nth-child(2){width:40%}
.analysis-summary th:nth-child(3){width:13%}
.analysis-summary th:nth-child(4){width:14%}
.analysis-summary th:nth-child(5){width:19%}
[data-testid=analysis-rows]{min-width:1040px}
[data-testid=analysis-rows] th:nth-child(1){width:24%}
[data-testid=analysis-rows] th:nth-child(2),[data-testid=analysis-rows] th:nth-child(3){width:30%}
[data-testid=analysis-rows] th:nth-child(4){width:16%}
.analysis-members{min-width:840px}
.analysis-members th:nth-child(1){width:16%}
